// Pure report maths for the Petali ID web app: Daily Summary / Weekly Report / Monthly Overview built from SYNCHRONISED documents.
// This is a port of the pure functions of the desktop's reports.js / metrics-rollup.js / health-history.js (those are bound to local files and
// cannot run on the server). The port is held to the desktop by test/fixtures/report-vectors.json, which is GENERATED by the desktop code:
// the same inputs must give the same outputs. Rules (same as the desktop): a reading that was not recorded is never 0, averages are
// sample-weighted, comparisons need real data on both sides, incomplete periods say so. Days are the computer's own local calendar days
// as recorded in the documents; date arithmetic here is on the day KEYS only (no time zone involved).
/* eslint-disable @typescript-eslint/no-explicit-any */
export const KINDS = ['daily', 'weekly', 'monthly'] as const;
export type ReportKind = (typeof KINDS)[number];
const DAY_RE = /^(\d{4})-(\d{2})-(\d{2})$/;
const MONTH_RE = /^(\d{4})-(\d{2})$/;
export const COMPARE: any = { weekly: { minDays: 3 }, monthly: { minDays: 7 }, minHardwareMinutes: 120 };
const RANK: Record<string, number> = { info: 1, warning: 2, critical: 3 };
export const MAX_EPISODES = 25;
const isNum = (v: unknown): v is number => typeof v === 'number' && Number.isFinite(v);
const sum = (a: number[]) => a.reduce((x, y) => x + y, 0);
const round1 = (v: number) => Math.round(v * 10) / 10;

// ---------------------------------------------------------------- calendar (day keys, no time zone)
export function parseDay(key: unknown): Date | null {
  const m = typeof key === 'string' ? DAY_RE.exec(key) : null;
  if (!m) return null;
  const y = Number(m[1]); const mo = Number(m[2]); const d = Number(m[3]);
  const date = new Date(Date.UTC(y, mo - 1, d, 12));
  return date.getUTCFullYear() === y && date.getUTCMonth() === mo - 1 && date.getUTCDate() === d ? date : null;     // rejects 2026-02-31
}
const keyOf = (d: Date) => d.toISOString().slice(0, 10);
export function addDays(key: string, n: number): string { const d = parseDay(key) as Date; return keyOf(new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate() + n, 12))); }
export const weekdayOf = (key: string): number => ((parseDay(key) as Date).getUTCDay() + 6) % 7;      // 0 = Monday ... 6 = Sunday
export const mondayOf = (key: string): string => addDays(key, -weekdayOf(key));
export function monthDays(month: string): string[] {
  const m = MONTH_RE.exec(month); if (!m) return [];
  const y = Number(m[1]); const mo = Number(m[2]);
  const n = new Date(Date.UTC(y, mo, 0)).getUTCDate();
  return Array.from({ length: n }, (_, i) => `${month}-${String(i + 1).padStart(2, '0')}`);
}
export function addMonths(month: string, n: number): string { const [y, m] = month.split('-').map(Number) as [number, number]; const d = new Date(Date.UTC(y, m - 1 + n, 15, 12)); return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, '0')}`; }

export type Period = { kind: ReportKind; key: string; dayKeys: string[]; elapsedKeys: string[]; from: string; to: string; isCurrent: boolean };
export function periodFor(kind: string, key: unknown, todayKey: string): Period | { error: 'invalid-kind' | 'invalid-key' | 'future-period' } {
  if (!(KINDS as readonly string[]).includes(kind)) return { error: 'invalid-kind' };
  let dayKeys: string[]; let canonical: string;
  if (kind === 'daily') {
    const c = key === undefined || key === null ? todayKey : key;
    if (typeof c !== 'string' || !parseDay(c)) return { error: 'invalid-key' };
    canonical = c; dayKeys = [c];
  } else if (kind === 'weekly') {
    const k = key === undefined || key === null ? todayKey : key;
    if (typeof k !== 'string' || !parseDay(k)) return { error: 'invalid-key' };
    canonical = mondayOf(k); dayKeys = Array.from({ length: 7 }, (_, i) => addDays(canonical, i));
  } else {
    const c = key === undefined || key === null ? todayKey.slice(0, 7) : key;
    if (typeof c !== 'string' || !MONTH_RE.test(c) || !parseDay(`${c}-01`)) return { error: 'invalid-key' };
    canonical = c; dayKeys = monthDays(c);
  }
  if ((dayKeys[0] as string) > todayKey) return { error: 'future-period' };
  return { kind: kind as ReportKind, key: canonical, dayKeys, elapsedKeys: dayKeys.filter((k) => k <= todayKey), from: dayKeys[0] as string, to: dayKeys[dayKeys.length - 1] as string, isCurrent: (dayKeys[dayKeys.length - 1] as string) >= todayKey };
}
export const neighbour = (kind: ReportKind, key: string, step: number): string => (kind === 'daily' ? addDays(key, step) : kind === 'weekly' ? addDays(key, 7 * step) : addMonths(key, step));

// ---------------------------------------------------------------- hardware buckets (metrics-rollup.js)
const METRIC_KEYS = ['cpu', 'ram', 'temp', 'gpu', 'fan'];
const EXT_KEYS = ['cpuW', 'gpuW', 'gpuMHz', 'gpuU', 'gpuMB', 'ramGB', 'bat', 'batV'];
const SERIES_KEYS = [...METRIC_KEYS, ...EXT_KEYS];
const MIN_KEYS = ['bat'];
const LATEST_KEYS = ['ssd', 'ramT', 'gpuMBT', 'bf', 'bd'];
const CODE_KEYS: Record<string, string> = { bs: 'bsm', hs: 'hsm' };
const BATTERY_UNITS = ['mWh', 'mAh'];

export function mergeBuckets(list: any[], t: number): any | null {
  if (!Array.isArray(list) || list.length === 0) return null;
  const ordered = [...list].sort((a, b) => a.t - b.t);
  let n = 0;
  const acc: Record<string, { sum: number; w: number; max: number; min: number }> = {};
  for (const k of SERIES_KEYS) acc[k] = { sum: 0, w: 0, max: -Infinity, min: Infinity };
  const latest: Record<string, number> = {};
  let unit: string | null = null;
  const codes: Record<string, number[]> = {};
  let ac = 0; let acSeen = false;
  for (const b of ordered) {
    n += b.n;
    for (const k of SERIES_KEYS) {
      const v = b[k]; const a = acc[k]!;
      if (Array.isArray(v) && isNum(v[0]) && isNum(v[1])) {
        a.sum += v[0] * b.n; a.w += b.n;
        if (v[1] > a.max) a.max = v[1];
        const lo = isNum(v[2]) ? v[2] : v[0];
        if (lo < a.min) a.min = lo;
      }
    }
    for (const k of LATEST_KEYS) if (isNum(b[k])) latest[k] = b[k];
    if (BATTERY_UNITS.includes(b.bu)) unit = b.bu;
    for (const [raw, s] of Object.entries(CODE_KEYS)) {
      if (Array.isArray(b[s])) {
        const c = codes[s] || (codes[s] = [0, 0, 0]);
        for (let i = 0; i < 3; i += 1) c[i]! += isNum(b[s][i]) ? b[s][i] : 0;
      } else if (Number.isInteger(b[raw]) && b[raw] >= 0 && b[raw] <= 2) {
        const c = codes[s] || (codes[s] = [0, 0, 0]);
        c[b[raw]]! += 1;
      }
    }
    if (isNum(b.ac)) { ac += b.ac; acSeen = true; }
  }
  const out: any = { t, n };
  for (const k of SERIES_KEYS) {
    const a = acc[k]!;
    if (a.w > 0) { out[k] = [round1(a.sum / a.w), a.max]; if (MIN_KEYS.includes(k)) out[k].push(a.min); }
  }
  for (const k of LATEST_KEYS) if (latest[k] !== undefined) out[k] = latest[k];
  if (unit !== null && (out.bf !== undefined || out.bd !== undefined)) out.bu = unit;
  for (const s of Object.values(CODE_KEYS)) if (codes[s]) out[s] = codes[s];
  if (acSeen) out.ac = ac;
  return out;
}

export const SERIES = [
  { id: 'cpuUsage', key: 'cpu', group: 'cpu', unit: '%', decimals: 1 },
  { id: 'cpuTemp', key: 'temp', group: 'cpu', unit: '°C', decimals: 1 },
  { id: 'cpuPower', key: 'cpuW', group: 'cpu', unit: 'W', decimals: 1 },
  { id: 'gpuUsage', key: 'gpuU', group: 'gpu', unit: '%', decimals: 1 },
  { id: 'gpuTemp', key: 'gpu', group: 'gpu', unit: '°C', decimals: 1 },
  { id: 'gpuPower', key: 'gpuW', group: 'gpu', unit: 'W', decimals: 1 },
  { id: 'gpuClock', key: 'gpuMHz', group: 'gpu', unit: 'MHz', decimals: 0 },
  { id: 'gpuMemory', key: 'gpuMB', group: 'gpu', unit: 'MB', decimals: 0 },
  { id: 'ramUsage', key: 'ram', group: 'ram', unit: '%', decimals: 1 },
  { id: 'ramUsed', key: 'ramGB', group: 'ram', unit: 'GB', decimals: 2 },
  { id: 'batteryLevel', key: 'bat', group: 'battery', unit: '%', decimals: 0, hasMin: true },
  { id: 'batteryVoltage', key: 'batV', group: 'battery', unit: 'V', decimals: 2 },
  { id: 'fan', key: 'fan', group: 'cooling', unit: 'RPM', decimals: 0 },
] as { id: string; key: string; group: string; unit: string; decimals: number; hasMin?: boolean }[];

export type HwDay = { hw: any; hourly: any[] };
export type HwMap = Map<string, HwDay>;

function peakOf(keys: string[], hw: HwMap, key: string) {
  let best: { value: number; t: number; level: string } | null = null;
  for (const k of keys) {
    const d = hw.get(k); if (!d) continue;
    const hourly = d.hourly.length > 0;
    for (const e of hourly ? d.hourly : [d.hw]) {
      const v = e[key];
      if (Array.isArray(v) && isNum(v[1]) && (!best || v[1] > best.value)) best = { value: v[1], t: e.t, level: hourly ? 'hour' : 'day' };
    }
  }
  return best;
}

export function aggregateHardware(keys: string[], hw: HwMap): any {
  const days = keys.map((k) => hw.get(k)).filter(Boolean) as HwDay[];
  const merged = mergeBuckets(days.map((d) => d.hw), 0);
  const minutes = sum(days.map((d) => d.hw.minutes || 0));
  const metrics: Record<string, any> = {};
  for (const def of SERIES) {
    const v = merged ? merged[def.key] : undefined;
    const ok = Array.isArray(v) && isNum(v[0]);
    metrics[def.id] = {
      id: def.id, unit: def.unit, decimals: def.decimals, available: ok,
      avg: ok ? v[0] : null, max: ok ? v[1] : null, min: ok && def.hasMin && isNum(v[2]) ? v[2] : null,
      maxAt: ok ? peakOf(keys, hw, def.key) : null,
      daysWithData: days.filter((d) => Array.isArray(d.hw[def.key])).length,
    };
  }
  return { merged, minutes, metrics, daysWithHardware: days.length };
}

export function batterySection(agg: any): any {
  const m = agg.merged || {};
  const bsm = Array.isArray(m.bsm) ? m.bsm : null;
  const level = agg.metrics.batteryLevel;
  const full = isNum(m.bf) ? m.bf : null; const design = isNum(m.bd) ? m.bd : null;
  return {
    recorded: level.available || !!bsm,
    level: { available: level.available, avg: level.avg, min: level.min, max: level.max },
    voltage: { available: agg.metrics.batteryVoltage.available, avg: agg.metrics.batteryVoltage.avg, min: null, max: agg.metrics.batteryVoltage.max },
    minutes: bsm ? { onBattery: bsm[0], charging: bsm[1], pluggedIn: bsm[2], total: bsm[0] + bsm[1] + bsm[2] } : null,
    capacity: full !== null || design !== null ? { full, design, unit: m.bu || null, healthPct: full !== null && design !== null && design > 0 ? Math.min(100, Math.round((full / design) * 100)) : null } : null,
  };
}

export function dayHardwareRows(keys: string[], hw: HwMap): any[] {
  const pick = (d: HwDay | undefined, key: string) => (d && Array.isArray(d.hw[key]) ? d.hw[key] : null);
  return keys.map((k) => {
    const d = hw.get(k);
    const cpu = pick(d, 'cpu'); const temp = pick(d, 'temp'); const gpuT = pick(d, 'gpu'); const ram = pick(d, 'ram'); const gpuU = pick(d, 'gpuU');
    return {
      dayKey: k, recordedMinutes: d ? d.hw.minutes || 0 : null,
      cpuAvg: cpu ? cpu[0] : null, cpuMax: cpu ? cpu[1] : null, tempAvg: temp ? temp[0] : null, tempMax: temp ? temp[1] : null,
      gpuTempMax: gpuT ? gpuT[1] : null, gpuUsageAvg: gpuU ? gpuU[0] : null, ramAvg: ram ? ram[0] : null, ramMax: ram ? ram[1] : null,
    };
  });
}

export function hourlyRows(day: string, hw: HwMap): any[] {
  const d = hw.get(day); if (!d) return [];
  return d.hourly.map((h) => ({
    t: h.t,
    cpuAvg: Array.isArray(h.cpu) ? h.cpu[0] : null, cpuMax: Array.isArray(h.cpu) ? h.cpu[1] : null,
    tempAvg: Array.isArray(h.temp) ? h.temp[0] : null, tempMax: Array.isArray(h.temp) ? h.temp[1] : null,
    ramAvg: Array.isArray(h.ram) ? h.ram[0] : null,
  }));
}

// ---------------------------------------------------------------- usage (Active Work)
export type ActiveDay = { activeMs: number; sessions: number; longestSessionMs: number };
export function usageSection(keys: string[], active: Map<string, ActiveDay>): any {
  const rows = keys.map((k) => {
    const a = active.get(k);
    return { dayKey: k, weekday: weekdayOf(k), activeMs: a ? a.activeMs : null, known: !!a, sessions: a ? a.sessions : 0, longestSessionMs: a ? a.longestSessionMs : 0 };
  });
  const known = rows.filter((r) => r.known);
  const activeDays = known.filter((r) => (r.activeMs as number) > 0);
  const totalMs = sum(known.map((r) => r.activeMs as number));
  let best: { dayKey: string; ms: number } | null = null;
  for (const r of activeDays) if (!best || (r.activeMs as number) > best.ms) best = { dayKey: r.dayKey, ms: r.activeMs as number };
  return {
    available: known.length > 0,
    totalMs: known.length ? totalMs : null,
    knownDays: known.length,
    activeDays: activeDays.length,
    avgPerKnownDayMs: known.length ? Math.round(totalMs / known.length) : null,
    avgPerActiveDayMs: activeDays.length ? Math.round(totalMs / activeDays.length) : null,
    bestDay: best,
    sessions: sum(known.map((r) => r.sessions)),
    longestSessionMs: known.reduce((a, r) => Math.max(a, r.longestSessionMs), 0),
    days: rows,
  };
}

// ---------------------------------------------------------------- Device Health (health-history.js buildEpisodes + reports.js healthSection)
export type HealthEvent = { k: string; id?: string; t: number; sev?: string; v?: unknown[]; why?: string };
export function buildEpisodes(events: HealthEvent[], { from = 0, to = Infinity }: { from?: number; to?: number } = {}): any[] {
  const byId = new Map<string, any>(); const done: any[] = []; const notifies: HealthEvent[] = [];
  for (const e of Array.isArray(events) ? events : []) {
    if (e.k === 'notify') { notifies.push(e); continue; }
    if (e.k === 'start') {
      if (byId.has(e.id as string)) done.push(byId.get(e.id as string));
      byId.set(e.id as string, { id: e.id, start: e.t, end: null, severity: e.sev, interrupted: false, notifications: 0, values: e.v || [] });
    } else if (e.k === 'sev') {
      const ep = byId.get(e.id as string);
      if (ep && (RANK[e.sev as string] ?? 0) > (RANK[ep.severity] ?? 0)) ep.severity = e.sev;
    } else if (e.k === 'end') {
      const ep = byId.get(e.id as string);
      if (ep) { ep.end = e.t; ep.interrupted = e.why === 'interrupted'; done.push(ep); byId.delete(e.id as string); }
    }
  }
  for (const ep of byId.values()) done.push(ep);
  for (const ep of done) {
    ep.durationMs = ep.end !== null && !ep.interrupted ? Math.max(0, ep.end - ep.start) : null;
    ep.notifications = notifies.filter((n) => n.id === ep.id && n.t >= ep.start && (ep.end === null || n.t <= ep.end)).length;
  }
  return done.filter((ep) => ep.start <= to && (ep.end === null || ep.end >= from)).sort((a, b) => a.start - b.start || (a.id < b.id ? -1 : 1));
}

export function healthSection(episodes: any[], events: HealthEvent[], agg: any): any {
  const hsm = agg.merged && Array.isArray(agg.merged.hsm) ? agg.merged.hsm : null;
  const evaluatedMinutes = hsm ? hsm[0] + hsm[1] + hsm[2] : 0;
  const notifications = events.filter((e) => e.k === 'notify').length;
  const byId = new Map<string, any>();
  for (const ep of episodes) {
    const cur = byId.get(ep.id) || { id: ep.id, count: 0, severity: ep.severity, totalMs: 0, durationKnown: true, lastAt: 0, notifications: 0 };
    cur.count += 1;
    if ((RANK[ep.severity] ?? 0) > (RANK[cur.severity] ?? 0)) cur.severity = ep.severity;
    if (ep.durationMs === null) cur.durationKnown = false; else cur.totalMs += ep.durationMs;
    cur.lastAt = Math.max(cur.lastAt, ep.start);
    cur.notifications += ep.notifications;
    byId.set(ep.id, cur);
  }
  const problems = [...byId.values()].sort((a, b) => (RANK[b.severity] ?? 0) - (RANK[a.severity] ?? 0) || b.count - a.count || (a.id < b.id ? -1 : 1)).map((p) => ({ ...p, totalMs: p.durationKnown ? p.totalMs : null }));
  const worst = episodes.reduce((w: string | null, ep) => (w === null || (RANK[ep.severity] ?? 0) > (RANK[w] ?? 0) ? ep.severity : w), null);
  return {
    recorded: evaluatedMinutes > 0 || events.length > 0,
    evaluatedMinutes,
    statusMinutes: hsm ? { healthy: hsm[0], warning: hsm[1], critical: hsm[2] } : null,
    episodeCount: episodes.length,
    worst, problems, notifications,
    episodes: episodes.slice(-MAX_EPISODES).map((ep) => ({ id: ep.id, severity: ep.severity, start: ep.start, end: ep.end, durationMs: ep.durationMs, interrupted: ep.interrupted, notifications: ep.notifications, values: ep.values })),
    episodesShown: Math.min(episodes.length, MAX_EPISODES),
  };
}

// ---------------------------------------------------------------- comparison with the previous period
const COMPARED = ['cpuUsage', 'cpuTemp', 'gpuUsage', 'gpuTemp', 'ramUsage'];
export function compare({ period, usage, agg, health, prev }: { period: Period; usage: any; agg: any; health: any; prev: { key: string; keys: string[]; usage: any; agg: any; health: any } }): any {
  const rule = COMPARE[period.kind];
  const none = (reason: string, extra: Record<string, unknown> = {}) => ({ available: false, reason, ...extra });
  if (!rule) return none('not-applicable');
  const n = period.elapsedKeys.length;
  if (n < rule.minDays) return none('current-too-short', { days: n, needDays: rule.minDays });
  const prevKnown = prev.usage.knownDays;
  if (usage.knownDays < rule.minDays || prevKnown < rule.minDays) return none(prevKnown === 0 ? 'no-previous-data' : 'too-few-days', { days: n, needDays: rule.minDays, currentDays: usage.knownDays, previousDays: prevKnown });
  const out: any = {
    available: true, reason: null, days: prev.keys.length, previousKey: prev.key, basis: 'average per recorded day',
    usage: {
      currentAvgMs: usage.avgPerKnownDayMs, previousAvgMs: prev.usage.avgPerKnownDayMs,
      deltaMs: usage.avgPerKnownDayMs - prev.usage.avgPerKnownDayMs,
      deltaPct: prev.usage.avgPerKnownDayMs > 0 ? Math.round(((usage.avgPerKnownDayMs - prev.usage.avgPerKnownDayMs) / prev.usage.avgPerKnownDayMs) * 1000) / 10 : null,
    },
    metrics: {}, episodes: null,
  };
  if (agg.minutes >= COMPARE.minHardwareMinutes && prev.agg.minutes >= COMPARE.minHardwareMinutes) {
    for (const id of COMPARED) {
      const c = agg.metrics[id]; const p = prev.agg.metrics[id];
      if (!c || !p || !c.available || !p.available) continue;
      out.metrics[id] = { unit: c.unit, currentAvg: c.avg, previousAvg: p.avg, deltaAvg: Math.round((c.avg - p.avg) * 10) / 10, currentMax: c.max, previousMax: p.max, deltaMax: Math.round((c.max - p.max) * 10) / 10 };
    }
  }
  if (health.evaluatedMinutes > 0 && prev.health.evaluatedMinutes > 0) out.episodes = { current: health.episodeCount, previous: prev.health.episodeCount };
  return out;
}
